namespace Ada {
 public sealed class UtilityDial:FrameworkElement {
  public double Value;public Brush Accent,Track;
  protected override void OnRender(DrawingContext dc){double r=Math.Min(ActualWidth,ActualHeight)/2-8;if(r<=0)return;var center=new Point(ActualWidth/2,ActualHeight/2);dc.DrawEllipse(null,new Pen(Track,5),center,r,r);double p=Math.Max(0,Math.Min(.99999,Value));if(p<=0)return;var path=new StreamGeometry();using(var g=path.Open()){g.BeginFigure(new Point(center.X,center.Y-r),false,false);double a=p*Math.PI*2;g.ArcTo(new Point(center.X+Math.Sin(a)*r,center.Y-Math.Cos(a)*r),new Size(r,r),0,p>.5,SweepDirection.Clockwise,true,false);}dc.DrawGeometry(null,new Pen(Accent,5){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round},path);}
 }
 public sealed partial class AdaWindow {
  UtilitySession tools;string timePage="Pomodoro",editingTask;TaskEntry removedTask;TextBox taskTitleInput,taskDueInput;StackPanel shelfRows,taskRows;TextBlock timerDigits,timerSubtitle,waterAmount,waterCaption,waterNext;UtilityDial timerDial,waterDial;Button timerRunButton;string activityCaption="";
  void PageHeading(string kicker,string title,string description){var heading=Label(title,20,true);heading.Margin=new Thickness(0,0,0,5);content.Children.Add(heading);var sub=Label(description,13,false,"Muted");sub.TextWrapping=TextWrapping.Wrap;sub.Margin=new Thickness(0,0,0,13);content.Children.Add(sub);}
  Button ActionButton(string name,string icon,Action action,bool primary=false){var b=MakeButton(name,ButtonContent(icon,name,17),action);b.MinHeight=42;b.Padding=new Thickness(14,9,14,9);if(primary){b.Background=(Brush)Resources["Action"];b.Foreground=(Brush)Resources["OnAction"];var row=b.Content as StackPanel;if(row!=null)foreach(var child in row.Children.OfType<TextBlock>())child.SetResourceReference(TextBlock.ForegroundProperty,"OnAction");if(row!=null&&row.Children.Count>0){var box=row.Children[0] as Viewbox;if(box!=null)foreach(var path in Descendants<System.Windows.Shapes.Path>(box))path.SetResourceReference(Shape.FillProperty,"OnAction");}}return b;}
  void PrimaryInk(Button button){var body=button.Content as DependencyObject;if(body==null)return;foreach(var text in Descendants<TextBlock>(body))text.SetResourceReference(TextBlock.ForegroundProperty,"OnAction");foreach(var path in Descendants<System.Windows.Shapes.Path>(body))path.SetResourceReference(Shape.FillProperty,"OnAction");}
  StackPanel ActionRow(params FrameworkElement[] controls){var row=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,12,0,10)};foreach(var control in controls){control.Margin=new Thickness(4,0,4,0);row.Children.Add(control);}return row;}
  void OpenLocal(string path){try{Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}catch(Exception ex){PublishNotice("file-error","Dosya açılamadı",ex.Message,"document","shelf");}}
  void RenderShelf(){
   PageHeading("Dosya rafı","Elinin altında.","Dosyaları buraya bırak. Kopyaları Belgeler / Veilix / Raf içinde saklanır.");
   var drop=new StackPanel{HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};drop.Children.Add(Glyph("folder",36,"Accent"));var text=Label(tools.Copying?"Dosyalar kopyalanıyor…":"Bırak, sonra kaldığın yerden devam et.",14,true);text.Margin=new Thickness(0,10,0,4);drop.Children.Add(text);var hint=Label("Dosya ve klasörleri sürükleyebilirsin",11,false,"Muted");hint.HorizontalAlignment=HorizontalAlignment.Center;drop.Children.Add(hint);
   var target=new Border{Height=100,CornerRadius=new CornerRadius(20),BorderThickness=new Thickness(1),Child=drop,Margin=new Thickness(0,0,0,14)};target.SetResourceReference(Border.BorderBrushProperty,"Track");target.SetResourceReference(Border.BackgroundProperty,"Nav");content.Children.Add(target);
