  }
  async void ImportShelf(string[] paths){if(tools.Copying)return;var work=tools.Import(paths);if(route=="shelf")RenderRoute(false);var errors=await work;if(closing)return;if(errors.Count>0)PublishNotice("shelf","Bazı dosyalar eklenemedi",String.Join("\n",errors.Take(2)),"folder","shelf");else PublishNotice("shelf","Rafın hazır",paths.Length+" öğe Belgeler klasörüne kopyalandı.","folder","shelf");}
  void RefreshShelfRows(){if(route!="shelf"||shelfRows==null)return;shelfRows.Children.Clear();if(tools.Data.Shelf.Count==0){var empty=Label("Henüz dosya yok. İlk dosyanı buraya bırak.",12,false,"Muted");empty.HorizontalAlignment=HorizontalAlignment.Center;empty.Margin=new Thickness(0,14,0,18);shelfRows.Children.Add(empty);return;}
   foreach(var entry in tools.Data.Shelf.AsEnumerable().Reverse()){
    var item=entry;var grid=new Grid{Margin=new Thickness(0,0,0,8)};grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(34)});
    var label=new StackPanel();label.Children.Add(Label(item.Name,13,true));var detail=Label(item.Folder?"Klasör · Aç veya dışarı sürükle":FileSize(item.Bytes)+" · Aç veya dışarı sürükle",10,false,"Muted");detail.Margin=new Thickness(0,4,0,0);label.Children.Add(detail);var body=new Grid();body.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(36)});body.ColumnDefinitions.Add(new ColumnDefinition());body.Children.Add(Glyph(item.Folder?"folder":"document",22,"Accent"));Grid.SetColumn(label,1);body.Children.Add(label);
    bool dragged=false;Point start=new Point();var open=MakeButton("Aç: "+item.Name,body,delegate{if(!dragged)OpenLocal(item.Path);});open.HorizontalContentAlignment=HorizontalAlignment.Stretch;open.Padding=new Thickness(10);open.PreviewMouseLeftButtonDown+=delegate(object sender,MouseButtonEventArgs e){start=e.GetPosition(this);dragged=false;};open.PreviewMouseMove+=delegate(object sender,MouseEventArgs e){if(e.LeftButton!=MouseButtonState.Pressed||dragged)return;var current=e.GetPosition(this);if(Math.Abs(current.X-start.X)+Math.Abs(current.Y-start.Y)<8)return;if(!File.Exists(item.Path)&&!Directory.Exists(item.Path))return;dragged=true;DragDrop.DoDragDrop(open,new DataObject(DataFormats.FileDrop,new[]{item.Path}),DragDropEffects.Copy|DragDropEffects.Link);};grid.Children.Add(open);
    var remove=IconButton("Raftan kaldır · Belgeler'deki kopya kalır","close",delegate{tools.Data.Shelf.Remove(item);tools.Save();RenderRoute(false);});remove.MinHeight=32;remove.Width=30;remove.Padding=new Thickness(4);remove.Background=Brushes.Transparent;Grid.SetColumn(remove,1);grid.Children.Add(remove);shelfRows.Children.Add(grid);
   }
  }
  static string FileSize(long bytes){return bytes>=1048576?(bytes/1048576.0).ToString("0.#")+" MB":bytes>=1024?(bytes/1024.0).ToString("0.#")+" KB":bytes+" B";}
  void RenderTime(){
   PageHeading("Zaman","Kendine bir ritim bul.","Odaklan, kısa bir sayaç başlat ya da geçen süreyi takip et.");
   var modes=new Grid{Margin=new Thickness(0,0,0,12)};foreach(var name in new[]{"Pomodoro","Zamanlayıcı","Kronometre"}){modes.ColumnDefinitions.Add(new ColumnDefinition());string mode=name;var b=MakeButton(mode,mode,delegate{SwitchTimeMode(mode);});b.FontSize=12;b.MinHeight=36;b.Padding=new Thickness(5,7,5,7);b.Margin=new Thickness(2);b.Background=(Brush)Resources[timePage==mode?"Selected":"Nav"];Grid.SetColumn(b,modes.Children.Count);modes.Children.Add(b);}content.Children.Add(modes);
   timeBody=new StackPanel();content.Children.Add(timeBody);RenderTimeBody();
  }
  void RenderTimeBody(){var outer=content;content=timeBody;try{
   var face=new Grid{Width=168,Height=168,HorizontalAlignment=HorizontalAlignment.Center};timerDial=new UtilityDial{Accent=(Brush)Resources["Accent"],Track=(Brush)Resources["Track"]};face.Children.Add(timerDial);var center=new StackPanel{VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Center};timerDigits=Label("00:00",38);timerDigits.FontFamily=new FontFamily("Bahnschrift, Segoe UI");timerDigits.HorizontalAlignment=HorizontalAlignment.Center;center.Children.Add(timerDigits);timerSubtitle=Label("",12,false,"Muted");timerSubtitle.HorizontalAlignment=HorizontalAlignment.Center;timerSubtitle.Margin=new Thickness(0,8,0,0);center.Children.Add(timerSubtitle);face.Children.Add(center);content.Children.Add(face);
   var state=timePage=="Pomodoro"?tools.Data.Pomodoro:tools.Data.Countdown;timerRunButton=ActionButton("Başlat","play",delegate{if(timePage=="Kronometre")tools.ToggleStopwatch();else tools.ToggleTimer(state);RenderRoute(false);},true);
   var reset=ActionButton("Sıfırla","undo",delegate{if(timePage=="Kronometre")tools.ResetStopwatch();else tools.ResetTimer(state,timePage=="Pomodoro"?(tools.Data.FocusPhase?tools.Data.FocusMinutes:tools.Data.BreakMinutes)*60:state.Total);RenderRoute(false);});content.Children.Add(ActionRow(timerRunButton,reset));
   if(timePage=="Pomodoro"){
    var phase=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,2,0,12)};foreach(bool focus in new[]{true,false}){bool isFocus=focus;var choice=MakeButton(isFocus?"Odak turu":"Kısa mola",isFocus?"Odak":"Mola",delegate{tools.Data.FocusPhase=isFocus;tools.ResetTimer(state,(isFocus?tools.Data.FocusMinutes:tools.Data.BreakMinutes)*60);RenderRoute(false);});choice.MinHeight=32;choice.Padding=new Thickness(18,5,18,5);choice.Margin=new Thickness(3);choice.Background=(Brush)Resources[tools.Data.FocusPhase==isFocus?"Selected":"Nav"];phase.Children.Add(choice);}content.Children.Add(phase);
    ToolCombo("Odak süresi",new[]{"15 dk","25 dk","30 dk","45 dk","60 dk"},tools.Data.FocusMinutes+" dk",delegate(string value){tools.Data.FocusMinutes=Int32.Parse(value.Split(' ')[0]);if(tools.Data.FocusPhase)tools.ResetTimer(state,tools.Data.FocusMinutes*60);tools.Save();RenderRoute(false);});
   }else if(timePage=="Zamanlayıcı"){
    var values=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,0,0,10)};foreach(int minutes in new[]{1,5,10,15,30}){int m=minutes;var b=MakeButton(m+" dakika",m+" dk",delegate{tools.ResetTimer(state,m*60);RenderRoute(false);});b.Margin=new Thickness(3);b.MinHeight=32;b.Padding=new Thickness(12,6,12,6);values.Children.Add(b);}content.Children.Add(values);
    var custom=new TextBox{Text=((int)(state.Total/60)).ToString(),Width=72,Margin=new Thickness(0,0,8,0),VerticalContentAlignment=VerticalAlignment.Center};AutomationProperties.SetName(custom,"Özel süre · dakika");var set=MakeButton("Dakikayı uygula","Dakika ayarla",delegate{int minutes;if(Int32.TryParse(custom.Text,out minutes)&&minutes>0&&minutes<=1440){tools.ResetTimer(state,minutes*60);RenderRoute(false);}else PublishNotice("input","Süreyi kontrol et","1 ile 1440 arasında bir dakika gir.","timer","time");});content.Children.Add(ActionRow(custom,set));
   }else{
    var lap=ActionButton("Tur ekle","add",delegate{if(tools.Data.Laps.Count>=20)tools.Data.Laps.RemoveAt(0);tools.Data.Laps.Add(tools.StopwatchElapsed);tools.Save();RenderRoute(false);});content.Children.Add(ActionRow(lap));int number=tools.Data.Laps.Count;foreach(double elapsed in tools.Data.Laps.AsEnumerable().Reverse().Take(5)){var line=new DockPanel{Margin=new Thickness(8,4,8,4)};var value=Label(UtilitySession.Format(elapsed)+"."+((int)(elapsed*10)%10),13);DockPanel.SetDock(value,Dock.Right);line.Children.Add(value);line.Children.Add(Label("Tur "+number--,12,false,"Muted"));content.Children.Add(line);}
   }
   Toggle("Süre bitince ses çal",tools.Data.TimerSound,delegate(bool value){tools.Data.TimerSound=value;tools.Save();});UpdateToolDisplays();
  }finally{content=outer;}}
  void ToolCombo(string name,string[] values,string selectedValue,Action<string> changed){var row=new Grid{Margin=new Thickness(0,5,0,7)};row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(140)});var label=Label(name,12,false,"Muted");label.VerticalAlignment=VerticalAlignment.Center;row.Children.Add(label);var box=new ComboBox{ItemsSource=values.Contains(selectedValue)?values:values.Concat(new[]{selectedValue}).ToArray(),SelectedItem=selectedValue,MinHeight=34,MaxDropDownHeight=240};if(box.SelectedIndex<0)box.SelectedIndex=0;AutomationProperties.SetName(box,name);box.SelectionChanged+=delegate{if(box.SelectedItem!=null)changed((string)box.SelectedItem);};Grid.SetColumn(box,1);row.Children.Add(box);content.Children.Add(row);}
  void CommitTask(){string title=taskTitleInput.Text.Trim();if(title.Length==0){taskTitleInput.Focus();return;}long due=0;string text=taskDueInput.Text.Trim();if(text.Length>0){DateTime when;if(!DateTime.TryParseExact(text,new[]{"H:mm","HH:mm","d.M.yyyy H:mm","dd.MM.yyyy HH:mm","yyyy-MM-dd HH:mm"},tr,DateTimeStyles.AllowWhiteSpaces,out when)){PublishNotice("task-input","Tarihi kontrol et","18:30 veya 27.10.2026 18:30 şeklinde yazabilirsin.","calendar","tasks");return;}if(text.IndexOf('.')<0&&text.IndexOf('-')<0){when=tools.Now.LocalDateTime.Date+when.TimeOfDay;if(when<tools.Now.LocalDateTime)when=when.AddDays(1);}due=new DateTimeOffset(DateTime.SpecifyKind(when,DateTimeKind.Local)).UtcTicks;}
   var task=editingTask==null?null:tools.Data.Tasks.FirstOrDefault(t=>t.Id==editingTask);if(task==null){task=new TaskEntry();tools.Data.Tasks.Add(task);}task.Title=title;task.DueUtc=due;task.Notified=false;editingTask=null;taskDraftTitle=taskDraftDue="";tools.Save();RenderRoute(false);
  }
  void RenderWater(){
   PageHeading("Su","Küçük yudumlar, iyi bir gün.","Günlük hedefini takip et. Hatırlatmalar senin saatlerine uysun.");
   var face=new Grid{Width=146,Height=146,HorizontalAlignment=HorizontalAlignment.Center};waterDial=new UtilityDial{Accent=(Brush)Resources["Accent"],Track=(Brush)Resources["Track"]};face.Children.Add(waterDial);var center=new StackPanel{HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};waterAmount=Label("0",34);waterAmount.HorizontalAlignment=HorizontalAlignment.Center;center.Children.Add(waterAmount);waterCaption=Label("",11,false,"Muted");waterCaption.HorizontalAlignment=HorizontalAlignment.Center;waterCaption.Margin=new Thickness(0,6,0,0);center.Children.Add(waterCaption);face.Children.Add(center);content.Children.Add(face);
   var drink=ActionButton("+ "+tools.Data.CupMl+" ml içtim","drop",delegate{tools.Drink(tools.Data.CupMl);RenderRoute(false);},true);content.Children.Add(ActionRow(drink,ActionButton("10 dk ertele","clock",delegate{tools.SnoozeWater();UpdateToolDisplays();})));
   waterNext=Label("",11,false,"Muted");waterNext.HorizontalAlignment=HorizontalAlignment.Center;waterNext.Margin=new Thickness(0,0,0,10);content.Children.Add(waterNext);
   Toggle("Su içmeyi hatırlat",tools.Data.WaterEnabled,delegate(bool value){tools.Data.WaterEnabled=value;tools.ResetWaterSchedule();UpdateToolDisplays();});Toggle("Hatırlatmada ses çal",tools.Data.WaterSound,delegate(bool value){tools.Data.WaterSound=value;tools.Save();});
   var preview=ActionButton("Hatırlatmayı dene","bell",delegate{Navigate("");PublishNotice(new UtilityNotice{Kind="water",Title="Bir bardak suya ne dersin?",Detail="Bu bir önizleme · "+tools.WaterMl+" / "+tools.Data.WaterGoal+" ml",Icon="drop",Route="water",Sound=tools.Data.WaterSound,Value=tools.WaterMl*100.0/tools.Data.WaterGoal});});preview.Background=Brushes.Transparent;content.Children.Add(preview);
   ToolCombo("Günlük hedef",new[]{"1500 ml","2000 ml","2500 ml","3000 ml","3500 ml","4000 ml"},tools.Data.WaterGoal+" ml",delegate(string value){tools.Data.WaterGoal=Int32.Parse(value.Split(' ')[0]);tools.Save();UpdateToolDisplays();});
   ToolCombo("Bardak / şişe",new[]{"150 ml","200 ml","250 ml","330 ml","500 ml","750 ml"},tools.Data.CupMl+" ml",delegate(string value){tools.Data.CupMl=Int32.Parse(value.Split(' ')[0]);tools.Save();RenderRoute(false);});
   ToolCombo("Hatırlatma sıklığı",new[]{"15 dk","30 dk","45 dk","60 dk","90 dk","120 dk"},tools.Data.WaterInterval+" dk",delegate(string value){tools.Data.WaterInterval=Int32.Parse(value.Split(' ')[0]);tools.ResetWaterSchedule();UpdateToolDisplays();});
   string[] hours=Enumerable.Range(0,24).Select(h=>h.ToString("00")+":00").ToArray();ToolCombo("Günün başlangıcı",hours,tools.Data.WaterFrom.ToString("00")+":00",delegate(string value){tools.Data.WaterFrom=Int32.Parse(value.Substring(0,2));tools.Save();UpdateToolDisplays();});ToolCombo("Günün sonu",hours,tools.Data.WaterTo.ToString("00")+":00",delegate(string value){tools.Data.WaterTo=Int32.Parse(value.Substring(0,2));tools.Save();UpdateToolDisplays();});
   if(tools.Data.Drinks.Count>0){var undo=ActionButton("Son bardağı geri al","undo",delegate{if(tools.Data.Drinks.Count>0)tools.Data.Drinks.RemoveAt(tools.Data.Drinks.Count-1);tools.Save();RenderRoute(false);});undo.Background=Brushes.Transparent;content.Children.Add(undo);}UpdateToolDisplays();
  }
  void UpdateToolDisplays(){if(tools==null)return;if(route=="time"&&timerDigits!=null){bool watch=timePage=="Kronometre";var timer=timePage=="Pomodoro"?tools.Data.Pomodoro:tools.Data.Countdown;double value=watch?tools.StopwatchElapsed:tools.Remaining(timer);string text=UtilitySession.Format(value)+(watch?"."+((int)(value*10)%10):"");if(timerDigits.Text!=text)timerDigits.Text=text;timerSubtitle.Text=watch?"Geçen süre":timePage=="Pomodoro"?(tools.Data.FocusPhase?"Odak zamanı":"Kısa mola"):"Kalan süre";double fill=watch?(value%60)/60:timer.Total<=0?0:1-value/timer.Total;if(Math.Abs(timerDial.Value-fill)>.000001){timerDial.Value=fill;timerDial.InvalidateVisual();}bool running=watch?tools.Data.StopwatchRunning:timer.Running;string caption=running?"Duraklat":"Başlat";if((string)timerRunButton.ToolTip!=caption){timerRunButton.Content=ButtonContent(running?"pause":"play",caption,17);timerRunButton.ToolTip=caption;PrimaryInk(timerRunButton);}}
   if(route=="water"&&waterAmount!=null){waterAmount.Text=(tools.WaterMl/1000.0).ToString("0.##",tr)+" L";waterCaption.Text="/ "+(tools.Data.WaterGoal/1000.0).ToString("0.##",tr)+" L";double fill=tools.WaterMl/(double)tools.Data.WaterGoal;if(Math.Abs(waterDial.Value-fill)>.000001){waterDial.Value=fill;waterDial.InvalidateVisual();}double remaining=Math.Max(0,(tools.Data.WaterNextUtc-tools.Now.UtcTicks)/(double)TimeSpan.TicksPerSecond);waterNext.Text=!tools.Data.WaterEnabled?"Hatırlatma kapalı":tools.WaterMl>=tools.Data.WaterGoal?"Bugünkü hedefine ulaştın.":!tools.WaterHours?"Aktif saatlerin dışında · sessizde":"Sonraki hatırlatma · "+UtilitySession.Format(remaining);}
  }
  void DecorateCompactActivity(bool music){if(tools==null||route!="")return;string caption=tools.Activity;if(caption.Length==0)return;miniArtist.Text=(music&&!String.IsNullOrWhiteSpace(Media.Artist)?Media.Artist+"  ·  ":"")+caption;miniArtist.Visibility=Visibility.Visible;}
 }
